	/**
	 * Default Constructor
	 */
    public RiskService(CurrentIdentity identity,
				ApplicationContext applicationContext)  {

		this.identity		= identity;
		this.projector 		= new RiskEntityProjector( applicationContext.getBean(ProjectorRegistry.class),
										applicationContext.getBean(RiskRepository.class) );
		this.validator		= applicationContext.getBean(RiskValidator.class) ;
	}


	/**
	 * Creates the provided command.
	 *
	 * @param		command ${class.getCreateCommandAlias()}
	 * @return		Risk
	 */
		public Risk createRisk( CreateRiskCommand command ) {

		Risk entity = new Risk();

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

            entity.setRiskId( command.getRiskId() );
            entity.setName( command.getName() );
            entity.setDescription( command.getDescription() );
            entity.setInherentRiskScore( command.getInherentRiskScore() );
            entity.setResidualRiskScore( command.getResidualRiskScore() );
            entity.setCategory( command.getCategory() );
            entity.setImpact( command.getImpact() );
            entity.setLikelihood( command.getLikelihood() );
            entity.setStatus( command.getStatus() );

		// ------------------------------------------
		// persist a new one
		// ------------------------------------------
		entity = projector.create(entity);

		LOGGER.info( "done creating of Risk {0} ", entity.toString() );

		return entity;
	}

	/**
	 * Update the provided command.
	 * @param		command UpdateRiskCommand
	 * @return		Risk
	 */
	public Risk updateRisk( UpdateRiskCommand command ) {

		Risk entity = new Risk();

		// --------------------------------------
		// validate
		// --------------------------------------
		validator.validate( command );

            entity.setRiskId( command.getRiskId() );
            entity.setName( command.getName() );
            entity.setDescription( command.getDescription() );
            entity.setInherentRiskScore( command.getInherentRiskScore() );
            entity.setResidualRiskScore( command.getResidualRiskScore() );
            entity.setOrganization( command.getOrganization() );
            entity.setControls( command.getControls() );
            entity.setAssessments( command.getAssessments() );
            entity.setIssues( command.getIssues() );
            entity.setFindings( command.getFindings() );
            entity.setCategory( command.getCategory() );
            entity.setImpact( command.getImpact() );
            entity.setLikelihood( command.getLikelihood() );
            entity.setStatus( command.getStatus() );

		// ------------------------------------------
		// persist an existing one
		// ------------------------------------------
		entity = projector.update(entity);

		LOGGER.info( "done saving of Risk {0} ", entity.toString() );

		return entity;
	}

	/**
	 * Deletes the associatied value object
	 * @param		command DeleteRiskCommand
	 */
	public void delete( DeleteRiskCommand command ) {
		UUID id = null;

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

		id = command.getRiskId();

		// ------------------------------------------
		// delete the entity
		// ------------------------------------------
		projector.delete(id);

		LOGGER.info( "done deleting of Risk {0} ", id );

	}

	/**
	 * Method to retrieve the Risk via RiskFetchOneSummary
	 * @param 	summary RiskFetchOneSummary
	 * @return 	RiskFetchOneResponse
	 */
	public Risk getRisk( RiskFetchOneSummary summary ) {

		if( summary == null )
			throw new IllegalStateException( "RiskFetchOneSummary arg cannot be null" );

		Risk entity = null;
		UUID id = summary.getRiskId();

		// --------------------------------------
		// validate the fetch one summary
		// --------------------------------------
		validator.validate( summary );

		// --------------------------------------
		// find a Risk using the provided id
		// --------------------------------------
		entity = projector.find( id );

		return entity;
	}


	/**
	 * Method to retrieve a collection of all Risks
	 *
	 * @return 	List<Risk>
	 */
    public List<Risk> getAllRisk() {
		List<Risk> list = projector.findAll( new FindAllRiskQuery() );
		return list;
	}

	/**
	 * assign Organization on Risk
	 * @param		command AssignOrganizationToRiskCommand
	 */
	public void assignOrganization( AssignOrganizationToRiskCommand command ) {
		// --------------------------------------
		// best to validate the command now
		// --------------------------------------
		validator.validate( command );

		// --------------------------------------
		// delegate to the projector
		// --------------------------------------
		projector.assignOrganization(command.getRiskId(), command.getAssignment());

	}

